document.addEventListener('selectionchange',()=>{clearTimeout(window._selT);window._selT=setTimeout(()=>{let sel=window.getSelection();if(!sel||sel.isCollapsed)return hideSelection();let text=sel.toString().trim();if(!text||text.length>60)return hideSelection();let node=sel.anchorNode,host=node&&(node.nodeType===1?node:node.parentElement);if(!host?.closest?.('.selectable'))return hideSelection();selectedText=text;$('selectionWord').textContent='「'+text+'」';$('selectionBar').classList.add('show')},220)});
function toast(msg){let x=$('toast');x.textContent=msg;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),1500)}
